<?php require __DIR__.'/cabecera.php';$valores=$entrada??$alergia??[];$activa=array_filter($alergias,static fn($a)=>$a['estado']==='activa'); ?>
<section class="panel clinico-panel"><h2>Alergias registradas</h2>
<?php if(!$alergias): ?><p role="status" data-clinico-sin-alergias>No hay registros de alergias. <?= ($perfil['estado_alergias']??'no_registrado')==='sin_conocidas'?'Un profesional indicó expresamente «sin alergias conocidas».':'Esto no confirma que el paciente no tenga alergias.' ?></p>
<?php elseif(!$activa): ?><p role="status">Hay antecedentes inactivos y ninguna entrada activa. Esto no declara ausencia de alergias conocidas automáticamente.</p><?php endif; ?>
<?php foreach($alergias as $a): ?><article class="clinico-alergia" data-clinico-alergia="<?= (int)$a['id'] ?>"><h3><?= e($a['sustancia']) ?> <span class="status-pill"><?= $a['estado']==='activa'?'Activa':'Inactiva' ?></span></h3>
<dl class="clinico-resumen"><dt>Reacción conocida</dt><dd><?= e($a['reaccion']??'No registrada') ?></dd><dt>Observaciones</dt><dd><?= e($a['observaciones']??'No registradas') ?></dd></dl>
<p class="field-hint">Creada por usuario #<?= (int)$a['creado_por_usuario_id'] ?> el <?= e($fechaClinica($a['creado_en'])) ?>. Última modificación por usuario #<?= (int)$a['actualizado_por_usuario_id'] ?> el <?= e($fechaClinica($a['actualizado_en'])) ?>. Versión <?= (int)$a['version'] ?>.</p>
<nav class="clinico-nav"><a class="text-link" href="<?= $baseClinica ?>/alergias/<?= (int)$a['id'] ?>/editar">Rectificar o cambiar estado</a><a class="text-link" href="<?= $baseClinica ?>/alergias/<?= (int)$a['id'] ?>/historial">Consultar revisiones</a></nav></article><?php endforeach; ?></section>
<section class="panel clinico-panel"><h2><?= $alergia?'Rectificar o cambiar estado':'Registrar alergia' ?></h2>
