<input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><?php if($alergia): ?><input type="hidden" name="version" value="<?= e((string)($valores['version']??$alergia['version'])) ?>"><?php endif; ?>
<?php foreach(['sustancia'=>['Sustancia o agente',120],'reaccion'=>['Reacción conocida (opcional)',250],'observaciones'=>['Observaciones (opcional)',500]] as $campo=>[$label,$max]): ?><div class="field-group"><label for="alergia-<?= e($campo) ?>"><?= e($label) ?></label><input id="alergia-<?= e($campo) ?>" name="<?= e($campo) ?>" maxlength="<?= $max ?>" value="<?= e($valores[$campo]??'') ?>" <?= $campo==='sustancia'?'required':'' ?>></div><?php endforeach; ?>
<?php if($alergia): ?><div class="field-group"><label for="alergia-estado">Estado del registro</label><select id="alergia-estado" name="estado"><option value="activa" <?= ($valores['estado']??'activa')==='activa'?'selected':'' ?>>Activa</option><option value="inactiva" <?= ($valores['estado']??'')==='inactiva'?'selected':'' ?>>Inactiva</option></select></div><div class="field-group"><label for="alergia-motivo">Motivo de la rectificación o cambio de estado</label><input id="alergia-motivo" name="motivo_cambio" maxlength="250" value="<?= e($valores['motivo_cambio']??'') ?>" required></div><p class="field-hint">Inactivar conserva el registro y sus versiones. No significa por sí solo que la alergia haya desaparecido.</p><?php endif; ?>
<label class="clinico-confirmar"><input type="checkbox" name="confirmar" value="1" required>Confirmo <?= $alergia?'la rectificación o cambio de estado y su motivo':'el registro de esta alergia' ?>.</label><button class="button" type="submit"><?= $alergia?'Guardar revisión':'Registrar alergia' ?></button><?php if($alergia): ?><a class="text-link" href="<?= $baseClinica ?>/alergias">Cancelar edición</a><?php endif; ?></form></section>
